html:
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro day(value) -%}{{ frappe.utils.format_date(value) if value else "" }}{%- endmacro -%}
{%- macro money(value) -%}{{ "{:,.0f}".format(value | float) if value else "" }}{%- endmacro -%}
{%- macro dots(n) -%}{% for i in range(n) %}&hellip;{% endfor %}{%- endmacro -%}
{%- set logo = frappe.db.get_single_value("HRMS Addon Branding", "company_logo") -%}
{%- set employee = frappe.get_doc("Employee", doc.employee) -%}
{%- macro addressee(on) -%}
{% if logo %}<p class="logo"><img src="{{ logo }}" style="max-height:64px"></p>{% endif %}
<p>{{ day(on) }}</p>
<p class="addr">{{ v(employee.salutation) }} {{ v(employee.employee_name) }}</p>
<p class="addr">{{ v(employee.employee_number or employee.name) }}</p>
<p class="addr">Division &ndash; {{ v(employee.department) }}</p>
<p class="addr">Plant, {{ v(employee.branch) }}</p>
<p>Dear {{ v(employee.first_name) }},</p>
{%- endmacro -%}
{%- macro signatory(setting, title) -%}
<div class="sign-off">
<p>&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;</p>
{%- set signer = frappe.db.get_single_value("Onboarding Settings", setting) -%}
<p class="who">{{ v(frappe.db.get_value("Employee", signer, "employee_name") if signer else "") }}</p>
<p class="who">{{ v(title) }}</p>
</div>
{%- endmacro -%}
{%- macro accepts(legal=0) -%}
<p style="margin-top:18px">I {{ v(employee.employee_name) }} &hellip;&hellip;&hellip;&hellip;&hellip; have received and agree to the above changes,</p>
<p>Sign &hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip; Date &hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;</p>
<p>Witness HRM &hellip;&hellip;&hellip;&hellip;&hellip; Sign &hellip;&hellip;&hellip;&hellip;&hellip; Date &hellip;&hellip;&hellip;&hellip;&hellip;</p>
{% if legal %}<p>Witness Legal Manager &hellip;&hellip;&hellip;&hellip;&hellip; Sign &hellip;&hellip;&hellip;&hellip;&hellip; Date &hellip;&hellip;&hellip;&hellip;&hellip;</p>{% endif %}
{%- endmacro -%}
<style>
.lpl-letter { font-family: Cambria, Georgia, serif; font-size: 12.5px; color: #000; line-height: 1.55; }
.lpl-letter p { margin: 0 0 12px; }
.lpl-letter .addr { font-weight: bold; margin: 0; }
.lpl-letter h4 { font-size: 12.5px; font-weight: bold; text-decoration: underline; margin: 14px 0 12px; }
.lpl-letter .logo { text-align: right; margin: 0 0 18px; }
.lpl-letter .sign-off { margin: 22px 0 0; }
.lpl-letter .who { font-weight: bold; text-transform: uppercase; margin: 0; }
.lpl-letter ol, .lpl-letter ul { margin: 0 0 12px 18px; padding: 0; }
.lpl-letter li { margin: 0 0 4px; }
.lpl-form table.grid { width: 100%; border-collapse: collapse; margin: 0 0 14px; }
.lpl-form table.grid th, .lpl-form table.grid td { border: 1px solid #000; padding: 5px 7px; font-size: 12px;
  text-align: left; vertical-align: top; }
.lpl-form table.grid th { background: #f2f2f2; font-weight: bold; }
.lpl-form .ref { width: 100%; border-collapse: collapse; margin: 0 0 14px; }
.lpl-form .ref td { border: 1px solid #000; padding: 4px 6px; font-size: 11px; }
.lpl-form h3 { font-size: 13px; text-align: center; text-transform: uppercase; margin: 10px 0 14px; }
.lpl-comment { border: 1px solid #000; padding: 8px 10px; margin: 0 0 12px; }
.lpl-comment .head { font-weight: bold; margin: 0 0 6px; }
.lpl-comment .body { min-height: 42px; white-space: pre-wrap; }
</style>
<div class="lpl-form lpl-letter">
<h3>Transfer Candidate Preamble</h3>
<table class="grid">
<tr><th style="width:32%">1. Personal Information</th><td>
Employee Name: {{ v(doc.employee_name) }}<br>
Employee ID: {{ v(doc.employee_number or doc.employee) }}<br>
Employee Contact: {{ v(doc.employee_contact) }}</td></tr>
<tr><th>2. Current Position</th><td>
Current job title: {{ v(doc.current_designation) }}<br>
Department: {{ v(doc.department) }}<br>
Date of hire: {{ day(doc.date_of_joining) }}<br>
Current manager/supervisor:
{{ v(frappe.db.get_value("Employee", doc.current_supervisor, "employee_name") if doc.current_supervisor else "") }}</td></tr>
<tr><th>3. Desired Position</th><td>{{ v(doc.desired_position or doc.new_designation) }}</td></tr>
<tr><th>4. Education</th><td>
{%- if doc.education %}
{%- for row in doc.education %}
Certification achieved: {{ v(row.certification) }}<br>
Name of institution: {{ v(row.institution) }}<br>
Major or field of study: {{ v(row.field_of_study) }}<br>
Graduation date: {{ day(row.graduation_date) }}<br>
{% if not loop.last %}<br>{% endif %}
{%- endfor %}
{%- endif %}
A&rsquo;level: {{ v(doc.a_level) }}<br>
O&rsquo;level: {{ v(doc.o_level) }}</td></tr>
<tr><th>5. Work Experience</th><td>
{%- for row in doc.experience %}
&bull; {{ v(row.designation) }} &mdash; {{ v(row.company) }} &mdash; {{ v(row.tenure) }}
{%- if row.responsibilities %}<br><span style="padding-left:12px">{{ v(row.responsibilities) }}</span>{% endif %}<br>
{%- endfor %}</td></tr>
<tr><th>6. Performance Evaluation</th><td>{{ v(doc.appraisal_score) }}{% if doc.appraisal_score %}%{% endif %}</td></tr>
</table>

{%- macro comment(title, remarks, by, on) -%}
<div class="lpl-comment">
<p class="head">Comments by the {{ title }}</p>
<div class="body">{{ v(remarks) }}</div>
<p style="margin:8px 0 0">Name {{ v(frappe.db.get_value("User", by, "full_name") if by else "") }}
&hellip;&hellip;&hellip;&hellip; Sign &hellip;&hellip;&hellip;&hellip;&hellip; Date {{ day(on) }} &hellip;&hellip;&hellip;&hellip;</p>
</div>
{%- endmacro -%}
{{ comment("Supervisor", doc.supervisor_remarks, doc.supervisor_by, doc.supervisor_on) }}
{{ comment("Human Resource Manager", doc.hrm_remarks, doc.hrm_by, doc.hrm_on) }}
{{ comment("General Manager", doc.gm_remarks, doc.gm_by, doc.gm_on) }}
{{ comment("Executive Director", doc.ed_remarks, doc.ed_by, doc.ed_on) }}
</div>
